window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[346]={"id":"346","numero":346,"titre":"Convulsions chez le nourrisson et l'enfant","objectifs":[{"id":"346-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux tableaux cliniques d’une crise convulsive du nourrisson et du jeune enfant","contenu":"<p>Le terme <span class=\"kw-def\">convulsions</span> désigne <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">manifestations motrices</span> d'une crise épileptique — mais il existe des crises épileptiques <strong>sans</strong> manifestation motrice.</p>\n      <p>Le diagnostic est <strong>purement clinique et anamnestique</strong> : <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">convulsions</span> ont le plus souvent <span class=\"kw-clinique\">cédé spontanément</span> lors de la 1<sup>re</sup> évaluation médicale. <span class=\"kw-alerte\">Aucun examen complémentaire</span> ne confirme ni n'infirme une convulsion a posteriori (risque important de <strong>diagnostic par excès</strong>) : il repose sur l'<span class=\"kw-clinique\">interrogatoire</span> de l'enfant et des <strong>témoins</strong> de l'épisode.</p>\n      <p>Si <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">convulsions</span> persistent <span class=\"kw-chiffre\">au-delà de 5 minutes</span> : <span class=\"kw-alerte\">état de mal au sens opérationnel</span> (prise en charge urgente spécifique).</p>\n      <p><strong>Sémiologie</strong> très variable ; certaines crises sont plus spécifiques :</p>\n      <ul>\n        <li>Crises <span class=\"kw-clinique\">généralisées tonicocloniques</span> — <span class=\"kw-chiffre\">rares avant 2 ans</span></li>\n        <li>Crises <span class=\"kw-clinique\">cloniques</span></li>\n        <li>Crises <span class=\"kw-clinique\">toniques</span></li>\n        <li>Crises <span class=\"kw-clinique\">atoniques</span></li>\n      </ul>\n      <p><strong>Diagnostics différentiels d'une convulsion</strong> (pièges fréquents) :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Diagnostic différentiel</span></th><th>Caractéristiques discriminantes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Frissons</span></td><td>À l'ascension thermique ou décharge <span class=\"kw-etio\">bactérienne</span> ; secousses <strong>moins amples et plus rapides</strong></td></tr>\n          <tr><td><span class=\"kw-clinique\">Trémulations</span></td><td>Tremblements fins des extrémités, <strong>disparaissant à l'immobilisation forcée</strong></td></tr>\n          <tr><td><span class=\"kw-clinique\">Myoclonies du sommeil</span></td><td>À l'endormissement, <strong>exclusivement dans le sommeil</strong></td></tr>\n          <tr><td><span class=\"kw-clinique\">Spasmes du sanglot</span></td><td>Séquence <span class=\"kw-clinique\">pleurs / apnée / cyanose</span> sur frustration, colère ou peur ; entre <span class=\"kw-chiffre\">6 mois et 3 ans</span> (plus rares après <span class=\"kw-chiffre\">5 ans</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Syncope vagale convulsivante</span></td><td>Perte de connaissance <strong>puis</strong> secousses des 4 membres</td></tr>\n          <tr><td><span class=\"kw-clinique\">Mouvements anormaux</span></td><td>Effets secondaires possibles de certains <span class=\"kw-ttt\">médicaments</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Autres malaises</span></td><td>Changement de teint brusque + <span class=\"kw-alerte\">rupture</span> de <span class=\"kw-def\">contact</span> + hypotonie, <strong>sans mouvement anormal</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Au terme de l'interrogatoire,</strong> préciser : crise <strong>certaine, probable ou possible</strong> ? et son type (<span class=\"kw-clinique\">à début généralisé, focal ou inconnu</span>) ?</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 105 — Epilepsie</em></p>","frequence":1},{"id":"346-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une crise convulsive hyperthermique simple et d’une crise convulsive complexe","contenu":"<p>Une <span class=\"kw-etio\">crise convulsive hyperthermique</span> (« crise fébrile ») est une crise épileptique liée à la <span class=\"kw-clinique\">fièvre</span> survenant chez un nourrisson/enfant <span class=\"kw-chiffre\">âgé de 6 mois à 5 ans</span> (le plus souvent <span class=\"kw-chiffre\">1 à 3 ans</span>), au <strong>développement psychomoteur normal</strong>, <strong>en dehors de toute atteinte du SNC</strong> (infectieuse ou non). ⚠️ La fièvre n'est pas indispensable au moment exact de la crise.</p>\n      <p><strong>Critères stricts de la crise hyperthermique simple</strong> : âge de début <span class=\"kw-chiffre\">> 1 an</span> · <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">> 37,5 °C</span> · manifestations motrices <strong>symétriques</strong> · durée <span class=\"kw-chiffre\">≤ 15 min</span> · <strong>pas de déficit post-critique</strong> · épisode <strong>unique</strong> pour un accès fébrile donné (<span class=\"kw-chiffre\">&lt; 3 épisodes au total</span>).</p>\n      <p>La présence d'<strong>un seul</strong> <span class=\"kw-def\">critère de</span> complexité suffit à classer la crise comme <span class=\"kw-alerte\">complexe (compliquée)</span> :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Crise fébrile SIMPLE</th><th>Crise fébrile COMPLEXE</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Âge</strong></td><td><span class=\"kw-chiffre\">1 – 5 ans</span></td><td><span class=\"kw-chiffre\">&lt; 1 an</span></td></tr>\n          <tr><td><strong>Durée</strong></td><td><span class=\"kw-chiffre\">brève (&lt; 15 min)</span> ; 1 seul épisode /<span class=\"kw-chiffre\"> 24 h</span></td><td><span class=\"kw-chiffre\">longue (≥ 15 min)</span> ; &gt; 1 épisode /<span class=\"kw-chiffre\"> 24 h</span></td></tr>\n          <tr><td><strong>Type</strong></td><td><span class=\"kw-clinique\">généralisée</span></td><td><span class=\"kw-clinique\">à début localisé (focal)</span></td></tr>\n          <tr><td><strong>Déficit post-critique</strong></td><td>non</td><td><span class=\"kw-alerte\">oui</span></td></tr>\n          <tr><td><strong>ATCD neurologiques</strong></td><td>non</td><td>oui</td></tr>\n          <tr><td><strong>Examen neurologique</strong></td><td><span class=\"kw-clinique\">normal</span></td><td><span class=\"kw-alerte\">anormal</span></td></tr>\n          <tr><td><strong>Examens complémentaires</strong></td><td>non</td><td>oui</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Hospitalisation</span></strong></td><td>non systématique</td><td><span class=\"kw-alerte\">systématique</span></td></tr>\n          <tr><td><strong>Traitement spécifique</strong></td><td>non</td><td>selon <span class=\"kw-clinique\">les</span> cas</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Conséquence pratique.</strong> Tous <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">critères de</span> simplicité réunis → <strong>simple</strong> : pas de bilan, pas d'<span class=\"kw-bio\">EEG</span>, pas d'antiépileptique au long cours, contrôle de l'<span class=\"kw-clinique\">hyperthermie</span>. <strong>Un seul</strong> critère manquant → <span class=\"kw-alerte\">complexe</span> : bilan étiologique ± antiépileptique de fond.</div>","frequence":1},{"id":"346-3","rang":"A","rubrique":"Étiologies","titre":"Connaître les étiologies des crises convulsives du nourrisson et du jeune enfant","contenu":"<p>Le <strong>contexte fébrile ou non</strong> structure l'enquête étiologique.</p>\n      <table >\n        <thead><tr><th>Contexte</th><th>Avant tout</th><th>Plus rarement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Crises AVEC <span class=\"kw-clinique\">fièvre</span></strong></td>\n            <td><span class=\"kw-etio\">Crise fébrile</span> ; <span class=\"kw-etio\">infection neuroméningée</span> (<span class=\"kw-alerte\">méningite bactérienne</span>, <span class=\"kw-alerte\">encéphalite herpétique</span>)</td>\n            <td><span class=\"kw-etio\">Neuropaludisme</span> ; <span class=\"kw-etio\">abcès cérébral</span> ; <span class=\"kw-etio\">thrombophlébite cérébrale</span> ; <span class=\"kw-etio\">SHU</span></td>\n          </tr>\n          <tr>\n            <td><strong>Crises SANS <span class=\"kw-clinique\">fièvre</span></strong></td>\n            <td><span class=\"kw-etio\">Événement occasionnel sans suite</span> (traumatisme crânien, <span class=\"kw-etio\">hématome sous-dural</span>) ; <span class=\"kw-etio\">1<sup>re</sup> crise d'une épilepsie débutante</span></td>\n            <td><span class=\"kw-etio\">Causes métaboliques</span> (surtout &lt;<span class=\"kw-chiffre\"> 6 mois</span>) ; <span class=\"kw-etio\">AVC</span> ; <span class=\"kw-etio\">tumeurs</span> ; <span class=\"kw-etio\">HTA</span> ; <span class=\"kw-etio\">SHU</span> ; <span class=\"kw-etio\">cause toxique</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Crises fébriles</strong> — <span class=\"kw-clinique\">les</span> crises épileptiques <strong>les plus fréquentes</strong> du nourrisson et du jeune enfant : <span class=\"kw-chiffre\">2 à 5 %</span> des enfants, fréquence majorée si <strong>ATCD familial</strong>. Ce sont des crises <strong>symptomatiques</strong> (≠ épilepsie), souvent d'origine <span class=\"kw-etio\">génétique</span>, déclenchées par l'élévation thermique (le plus souvent <span class=\"kw-etio\">infections virales</span> : ex. <span class=\"kw-etio\">exanthème subit</span>).</p>\n      <p><strong>Causes hors <span class=\"kw-clinique\">fièvre</span> — détails :</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">HSD / HED aigu</span> : complique un <span class=\"kw-clinique\">traumatisme crânien</span> ; <span class=\"kw-clinique\">fontanelle bombante</span> ; évoquer la <span class=\"kw-alerte\">maltraitance</span> chez le jeune nourrisson</li>\n        <li><span class=\"kw-etio\">Causes tumorales</span> : signes d'<span class=\"kw-clinique\">HTIC</span>, ↑ du <span class=\"kw-clinique\">périmètre crânien</span>, anomalie de l'examen neurologique</li>\n        <li><span class=\"kw-etio\">Causes neurovasculaires</span> : <span class=\"kw-etio\">AVC</span> (cardiopathie emboligène, <span class=\"kw-alerte\">rupture</span> de MAV ou d'anévrisme), <span class=\"kw-etio\">HTA</span></li>\n        <li><span class=\"kw-etio\">Causes toxiques</span> : <span class=\"kw-etio\">CO</span>, antidépresseurs, <span class=\"kw-etio\">alcool</span>, anti-<span class=\"kw-chiffre\">H2</span></li>\n        <li><span class=\"kw-etio\">Causes métaboliques</span> (surtout <span class=\"kw-chiffre\">&lt; 6 mois</span>) : hypo/<span class=\"kw-alerte\">hypernatrémie</span>, <span class=\"kw-bio\">hypoglycémie</span>, <span class=\"kw-bio\">hypocalcémie</span></li>\n      </ul>\n      <p><strong>Épilepsies du nourrisson</strong> à connaître : <span class=\"kw-etio\">syndrome de West</span> ; <span class=\"kw-etio\">syndrome de Dravet</span> (rare, <span class=\"kw-etio\">génétique</span> — mutation <em>de novo</em> de <span class=\"kw-bio\">SCN1A</span> dans <span class=\"kw-chiffre\">90 %</span> des cas ; crises prolongées fébriles ou post-vaccinales dès la 1<sup>re</sup> année → toute répétition de crises prolongées avant <span class=\"kw-chiffre\">1 an</span> impose un <strong>avis neuropédiatre</strong>).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-clinique\">Méningite</span> - méningoencéphalite · 170 — <span class=\"kw-clinique\">Paludisme</span> · 57 — Maltraitance, enfant en danger · 240 — Hypoglycémie · 267 — Trouble de l'équilibre acido-basique - Désordre hydro-électrolytique · 105 — Epilepsie</em></p>","frequence":1},{"id":"346-4","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes de gravité à rechercher devant une crise convulsive du nourrisson et du jeune enfant","contenu":"<p>Deux ordres de gravité à distinguer : ce qui tient à <strong>la crise elle-même</strong> et ce qui tient à <strong>sa cause</strong>.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\">Urgence</span> liée à…</th><th><span class=\"kw-alerte\">Signes de gravité</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>… la convulsion</strong></td>\n            <td>\n              <strong>Durée :</strong> crise <span class=\"kw-alerte\">&gt; 15 min</span> ; au-delà de <span class=\"kw-chiffre\">5 min</span> elle a plus de risque de durer que de s'arrêter (<span class=\"kw-chiffre\">5 min</span> = définition opérationnelle de l'<span class=\"kw-alerte\">état de mal</span> → BZD de secours)<br>\n              <strong>Récidive :</strong> crise <span class=\"kw-alerte\">récidivant sans retour à la conscience</span> normale<br>\n              <strong>Neurologiques :</strong> <span class=\"kw-clinique\">signes focaux durables</span> ; <span class=\"kw-clinique\">troubles de conscience prolongés</span> (caractère stable ou s'aggravant entre 2 examens à<span class=\"kw-chiffre\"> 15–30 min</span>)<br>\n              <strong>Respiratoires :</strong> <span class=\"kw-alerte\">bradypnée</span>, irrégularités, <span class=\"kw-alerte\">apnées</span>, <span class=\"kw-alerte\">cyanose</span>, encombrement bronchique majeur<br>\n              <strong>Hémodynamiques :</strong> <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">TRC allongé</span>, <span class=\"kw-clinique\">marbrures</span>, extrémités froides, <span class=\"kw-clinique\">pouls périphériques</span> mal perçus\n            </td>\n          </tr>\n          <tr>\n            <td><strong>… la cause</strong></td>\n            <td>\n              <strong><span class=\"kw-etio\">Infectieux</span> :</strong> <span class=\"kw-alerte\">sepsis</span>, <span class=\"kw-alerte\">purpura fébrile</span>, cris geignards, <span class=\"kw-clinique\">syndrome méningé</span>, signes encéphalitiques<br>\n              <strong>Maltraitance :</strong> <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-alerte\">hématomes multiples</span><br>\n              <strong><span class=\"kw-etio\">Toxique</span> :</strong> <span class=\"kw-alerte\">coma</span>, <span class=\"kw-alerte\">intoxication médicamenteuse</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Toute crise <span class=\"kw-alerte\">&gt; 5 minutes</span>, récidivante sans reprise de conscience, ou associée à des signes respiratoires / hémodynamiques impose une prise en charge d'<strong><span class=\"kw-alerte\">état de mal</span></strong> sans délai.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span> · 215 — <span class=\"kw-clinique\">Purpura</span></em></p>","frequence":0},{"id":"346-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge thérapeutique de première intention d’une crise convulsive du nourrisson et du jeune enfant avec la posologie des benzodiazépines par voie rectale (clonazepam ou diazepam)","contenu":"<p>Si <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">convulsions</span> ont <strong>cédé spontanément</strong> (le plus souvent) : <span class=\"kw-ttt\">antipyrétique</span> si <span class=\"kw-clinique\">fièvre</span> + <strong>traitement étiologique</strong>.</p>\n      <p><strong>Définitions :</strong> <span class=\"kw-def\">état de mal épileptique (EME)</span> = crises continues ou successives sans amélioration de la conscience sur <span class=\"kw-chiffre\">30 min</span> ; <span class=\"kw-def\">EME menaçant</span> = crise <span class=\"kw-chiffre\">&gt; 5 min</span> (définition <strong>opérationnelle</strong> — c'est le seuil à partir duquel on agit).</p>\n      <p><strong>CAT devant une crise persistante / récidivante</strong> (escalade thérapeutique) :</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Mesures générales</strong></td><td>Liberté des VAS : mise en <span class=\"kw-clinique\">PLS</span> (<span class=\"kw-alerte\">pas de canule de Guedel</span>) ; monitoring cardiorespiratoire ; constantes avec <span class=\"kw-clinique\">température</span></td></tr>\n          <tr><td><strong>1<sup>re</sup> intention</strong> (crise &gt;<span class=\"kw-chiffre\"> 5 min</span>)</td><td><span class=\"kw-ttt\">Benzodiazépine</span> : <span class=\"kw-ttt\">diazépam 0,5 mg/kg</span> (<span class=\"kw-chiffre\">max 10 mg</span>) en <strong>intrarectal</strong>, ou <span class=\"kw-ttt\">midazolam buccal</span></td></tr>\n          <tr><td><strong>2<sup>e</sup> intention</strong> (échec à<span class=\"kw-chiffre\"> 10 min</span>, soit <span class=\"kw-chiffre\">5 min</span> après la 1<sup>re</sup> injection)</td><td>2<sup>nde</sup> dose de <span class=\"kw-ttt\">benzodiazépine</span>, de préférence <strong>IV</strong> en milieu hospitalier : <span class=\"kw-ttt\">clonazépam IVL</span></td></tr>\n          <tr><td><strong>3<sup>e</sup> intention</strong> (nouvel échec)</td><td><span class=\"kw-ttt\">Phénytoïne</span> ou <span class=\"kw-ttt\">phénobarbital</span> par voie <strong>IV</strong>, au mieux en <strong><span class=\"kw-alerte\">réanimation</span> infantile</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Posologie BZD à retenir (rang A).</strong> <span class=\"kw-ttt\">Diazépam 0,5 mg/kg</span> intrarectal, <span class=\"kw-chiffre\">maximum 10 mg</span>, si la crise dure <span class=\"kw-chiffre\">&gt; 5 min</span>.</div>\n      <div class=\"callout callout-info\"><strong>CAT en cas de récidive à domicile.</strong> 1) administrer le <span class=\"kw-ttt\">diazépam intrarectal</span> si la crise n'a pas cédé à <span class=\"kw-chiffre\">5 min</span> ; 2) si persistance malgré cela → prévenir <span class=\"kw-clinique\">les</span> <strong>secours médicalisés</strong> ; 3) <strong>consultation médicale systématique</strong> même si la crise a cédé (rechercher la cause de la <span class=\"kw-clinique\">fièvre</span> + vérifier l'état neurologique).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 105 — Epilepsie</em></p>","frequence":0},{"id":"346-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications de ponction et d’imagerie cérébrale lors d’une crise convulsive du nourrisson et du jeune enfant","contenu":"<div class=\"callout callout-warn\"><strong>Règle d'or.</strong> Une <strong>crise fébrile simple ne nécessite aucun examen complémentaire</strong> (hors bilan de la <span class=\"kw-clinique\">fièvre</span> éventuellement indiqué). Une <span class=\"kw-bio\">surveillance hospitalière courte</span> (<span class=\"kw-chiffre\">4 h</span>) peut s'envisager chez le nourrisson de <span class=\"kw-chiffre\">&lt; 12 mois</span>.</div>\n      <table >\n        <thead><tr><th>Examen</th><th>Convulsion FÉBRILE</th><th>Convulsion NON fébrile</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Ponction</span> lombaire</strong></td>\n            <td>\n              <strong>Systématique</strong> si <span class=\"kw-chiffre\">âge &lt; 6 mois</span> (même isolée et résolutive)<br>\n              <strong>Suspicion de <span class=\"kw-alerte\">méningite</span> :</strong> <span class=\"kw-clinique\">fontanelle bombante</span>, anomalie du tonus, <span class=\"kw-clinique\">fièvre</span> mal tolérée<br>\n              <strong>Signes d'<span class=\"kw-alerte\">encéphalite</span> :</strong> trouble du comportement, <span class=\"kw-clinique\">crise focale</span>, crise <span class=\"kw-chiffre\">&gt; 15 min</span>, <span class=\"kw-clinique\">déficit focal post-critique</span>\n            </td>\n            <td><span class=\"kw-alerte\">Non indiquée</span></td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie cérébrale (<span class=\"kw-imagerie\">TDM injectée</span>)</strong></td>\n            <td>\n              Absence d'amélioration des <span class=\"kw-clinique\">troubles de la conscience</span><br>\n              Absence d'amélioration d'une <span class=\"kw-clinique\">anomalie neurologique focale</span> entre 2 examens séparés de <span class=\"kw-chiffre\">≥ 30 min</span><br>\n              <em>(le <span class=\"kw-imagerie\">scanner</span> avant PL n'est <strong>pas</strong> systématique)</em>\n            </td>\n            <td>\n              <span class=\"kw-chiffre\">Âge &lt; 1 an</span><br>\n              Signe de <span class=\"kw-clinique\">localisation</span> à l'examen<br>\n              Troubles de conscience <span class=\"kw-chiffre\">&gt; 30 min après la fin</span> de la crise\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">EEG</span></strong></td>\n            <td>Pas un examen d'<span class=\"kw-alerte\">urgence</span> (sauf doute sur la persistance de crises) ; <strong>inutile</strong> si crise fébrile simple</td>\n            <td>Pas en <span class=\"kw-alerte\">urgence</span> ; <strong>systématique après une 1<sup>re</sup> crise non fébrile</strong> ou une crise inhabituelle chez un épileptique connu</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Glycémie</span></strong></td>\n            <td colspan=\"2\"><span class=\"kw-chiffre\">Âge &lt; 1 an</span> ; <span class=\"kw-alerte\">signes de gravité</span> ; contexte évocateur (<span class=\"kw-bio\">diabète</span> sous <span class=\"kw-ttt\">insuline</span>, réveil après resucrage). Sans intérêt chez l'enfant &gt;<span class=\"kw-chiffre\"> 1 an</span> sans <span class=\"kw-alerte\"><span class=\"kw-def\">critère de</span> gravité</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Biologie</strong></td>\n            <td colspan=\"2\">Non systématique : <span class=\"kw-bio\">NFS-plaquettes</span>, <span class=\"kw-bio\">ionogramme (natrémie)</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">glycémie</span>. Indications : âge <span class=\"kw-chiffre\">&lt; 6 mois</span> ; <span class=\"kw-alerte\">signes de gravité</span> ; contexte particulier (<span class=\"kw-clinique\">déshydratation</span>, <span class=\"kw-clinique\">diarrhée</span> glairosanglante, <span class=\"kw-etio\">diabète</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-clinique\">Méningite</span> - méningoencéphalite</em></p>","frequence":0},{"id":"346-7","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître le pronostic d’une crise convulsive du nourrisson et du jeune enfant","contenu":"<p>Le <span class=\"kw-def\">pronostic</span> d'une crise fébrile s'évalue par <strong>4 questions pratiques</strong> :</p>\n      <table >\n        <thead><tr><th>Question</th><th>Facteurs prédictifs</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Infection cérébroméningée ?</strong></td><td><span class=\"kw-clinique\">Syndrome méningé</span> ; <span class=\"kw-def\">critères de</span> crise <span class=\"kw-alerte\">complexe</span> : <span class=\"kw-clinique\">focale</span> et/ou <span class=\"kw-clinique\">prolongée</span> et/ou <span class=\"kw-clinique\">répétitive sur 24 h</span></td></tr>\n          <tr><td><strong>Risque de récidive ?</strong></td><td>1<sup>re</sup> crise avant <span class=\"kw-chiffre\">&lt; 15 mois</span> ; <span class=\"kw-etio\">ATCD familial au 1<sup>er</sup> degré</span> ; <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">&lt; 38,5 °C</span> lors de la crise ; crise survenue <strong>tôt</strong> dans l'épisode fébrile</td></tr>\n          <tr><td><strong>Risque de crise prolongée ?</strong></td><td>1<sup>re</sup> crise (non prédictible) ; antécédent d'une crise <span class=\"kw-chiffre\">&gt; 10 min</span></td></tr>\n          <tr><td><strong>Risque d'épilepsie ultérieure ?</strong></td><td><span class=\"kw-alerte\">Retard psychomoteur</span> ; examen neurologique antérieurement anormal (<span class=\"kw-clinique\">déficit focal</span>, hémiparésie) ; crises <span class=\"kw-alerte\">complexes</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Risque principal = récidive</strong> d'une crise fébrile : <span class=\"kw-chiffre\">20–30 %</span> globalement. Gradient selon le nombre de <span class=\"kw-def\">facteurs de risque</span> : <span class=\"kw-chiffre\">0 FR → 10 %</span> · <span class=\"kw-chiffre\">1 FR → 25 %</span> · <span class=\"kw-chiffre\">2 FR → 50 %</span> · <span class=\"kw-chiffre\">3 FR → 80 %</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">antipyrétiques</span> ne préviennent <strong>pas</strong> la récurrence des crises fébriles au cours d'un épisode fébrile.</div>\n      <p><strong>Avis neuropédiatre requis</strong> si : crise fébrile prolongée avant <span class=\"kw-chiffre\">&lt; 1 an</span> (évoquer un <span class=\"kw-etio\">syndrome de Dravet</span>) ; crise <span class=\"kw-clinique\">focale et prolongée</span> ou <span class=\"kw-clinique\">focale et répétitive</span> ; répétition d'une crise complexe ; <span class=\"kw-alerte\">retard de développement</span> ou anomalie de l'examen neurologique. Le neuropédiatre décide d'un éventuel <span class=\"kw-ttt\">traitement antiépileptique préventif</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 105 — Epilepsie</em></p>","frequence":0}],"astuces":[{"type":"info","titre":"Astuces & pièges et stratégie","contenu":"<p>Couches « Astuces de PU &amp; Pièges » et « Stratégie &amp; CAT » : à compléter après revue clinique.</p>"}],"strategie":{"urgence":"<p><strong>Seuils temporels <span class=\"q\">— définir l'<span class=\"kw-alerte\">état de mal</span></span></strong></p><p>Dès <span class=\"kw-chiffre\">5 min</span> → <span class=\"kw-ttt\">benzodiazépine</span> de secours sans attendre</p><ul><li>Crise <span class=\"kw-chiffre\">&gt; 5 min</span> = <span class=\"kw-def\">EME menaçant</span> : définition <strong>opérationnelle</strong>, seuil à partir duquel on agit</li><li>Au-delà de <span class=\"kw-chiffre\">5 min</span>, la crise a plus de risque de durer que de céder spontanément</li><li><span class=\"kw-def\">État de mal épileptique</span> = crises continues / successives sans reprise de conscience sur <span class=\"kw-chiffre\">30 min</span></li></ul><p><strong>Traitement de secours <span class=\"q\">— posologie rang A</span></strong></p><p>Échec à <span class=\"kw-chiffre\">10 min</span> (<span class=\"kw-chiffre\">5 min</span> après la 1<sup>re</sup> dose) → relais <strong>IV</strong> en milieu hospitalier</p><ul><li><span class=\"kw-ttt\">Diazépam 0,5 mg/kg</span> en <strong>intrarectal</strong>, <span class=\"kw-chiffre\">max 10 mg</span>, si crise <span class=\"kw-chiffre\">&gt; 5 min</span></li><li>Alternative : <span class=\"kw-ttt\">midazolam buccal</span></li></ul>","hospit":"<p><strong>Crise fébrile <span class=\"q\">SIMPLE</span></strong></p><p>Retour à domicile après <strong>information et réassurance des parents</strong> sur la bénignité</p><ul><li>Pas d'<span class=\"kw-alerte\">hospitalisation</span> systématique</li><li><span class=\"kw-bio\">Surveillance hospitalière courte</span> (<span class=\"kw-chiffre\">4 h</span>) envisageable chez le nourrisson de <span class=\"kw-chiffre\">&lt; 12 mois</span></li></ul><p><strong>Crise fébrile <span class=\"q\">COMPLEXE</span></strong></p><ul><li><strong><span class=\"kw-alerte\">Hospitalisation</span> systématique</strong></li><li>Déclenche le <strong>bilan étiologique</strong> ± <span class=\"kw-ttt\">antiépileptique de fond</span></li></ul><p><strong>Avis neuropédiatre <span class=\"q\">— situations requises</span></strong></p><p>Le neuropédiatre décide d'un éventuel <span class=\"kw-ttt\">traitement antiépileptique préventif</span></p><ul><li>Crise fébrile <span class=\"kw-clinique\">prolongée</span> avant <span class=\"kw-chiffre\">&lt; 1 an</span> (évoquer un <span class=\"kw-etio\">syndrome de Dravet</span>)</li><li>Crise <span class=\"kw-clinique\">focale et prolongée</span> ou <span class=\"kw-clinique\">focale et répétitive</span></li><li>Répétition d'une crise <span class=\"kw-alerte\">complexe</span></li><li><span class=\"kw-alerte\">Retard de développement</span> ou anomalie de l'examen neurologique</li></ul>","redflags":"<ul><li>Crise <span class=\"kw-alerte\">&gt; 15 min</span> (au-delà de <span class=\"kw-chiffre\">5 min</span> : risque accru de durer → <span class=\"kw-alerte\">état de mal</span>)</li><li>Crise <span class=\"kw-alerte\">récidivant sans retour à la conscience</span> normale</li><li><span class=\"kw-clinique\">Signes neurologiques focaux durables</span> ou <span class=\"kw-alerte\">troubles de la conscience prolongés</span> (stables / s'aggravant entre 2 examens à <span class=\"kw-chiffre\">15–30 min</span>)</li><li><span class=\"kw-alerte\">Détresse</span> respiratoire : <span class=\"kw-alerte\">bradypnée</span>, <span class=\"kw-alerte\">apnées</span>, <span class=\"kw-alerte\">cyanose</span>, encombrement bronchique majeur</li><li>Instabilité hémodynamique : <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">TRC allongé</span>, <span class=\"kw-clinique\">marbrures</span>, extrémités froides</li><li>Cause infectieuse : <span class=\"kw-alerte\">sepsis</span>, <span class=\"kw-alerte\">purpura fébrile</span>, <span class=\"kw-clinique\">syndrome méningé</span>, signes encéphalitiques</li><li>Suspicion de <span class=\"kw-alerte\">maltraitance</span> : <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-alerte\">hématomes multiples</span></li><li>Cause <span class=\"kw-etio\">toxique</span> : <span class=\"kw-alerte\">coma</span>, <span class=\"kw-alerte\">intoxication médicamenteuse</span></li></ul>","principes":"<p>Si <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">convulsions</span> ont <strong>cédé spontanément</strong> (le plus souvent) : <span class=\"kw-ttt\">antipyrétique</span> si <span class=\"kw-clinique\">fièvre</span> + <strong>traitement étiologique</strong>. Crise fébrile simple → <strong>rassurer les parents</strong> sur sa bénignité.</p><p><strong>Mesures générales <span class=\"q\">— crise persistante</span></strong></p><ul><li>Liberté des VAS : mise en <span class=\"kw-clinique\">PLS</span></li><li><span class=\"kw-ci\">Pas de canule de Guedel</span></li><li><span class=\"kw-bio\">Monitoring cardiorespiratoire</span> + constantes avec <span class=\"kw-clinique\">température</span></li></ul><p><strong>Escalade médicamenteuse</strong></p><ul><li><strong>1<sup>re</sup> intention</strong> (crise <span class=\"kw-chiffre\">&gt; 5 min</span>) : <span class=\"kw-ttt\">diazépam 0,5 mg/kg intrarectal</span> (<span class=\"kw-chiffre\">max 10 mg</span>) ou <span class=\"kw-ttt\">midazolam buccal</span></li><li><strong>2<sup>e</sup> intention</strong> (échec à <span class=\"kw-chiffre\">10 min</span>, soit <span class=\"kw-chiffre\">5 min</span> après la 1<sup>re</sup> dose) : 2<sup>e</sup> <span class=\"kw-ttt\">benzodiazépine</span>, de préférence IV — <span class=\"kw-ttt\">clonazépam IVL</span> en milieu hospitalier</li><li><strong>3<sup>e</sup> intention</strong> (nouvel échec) : <span class=\"kw-ttt\">phénytoïne</span> ou <span class=\"kw-ttt\">phénobarbital</span> IV, au mieux en <strong><span class=\"kw-alerte\">réanimation</span> infantile</strong></li></ul><p><strong>Récidive fébrile à domicile</strong></p><p><strong>Consultation médicale systématique</strong> même si la crise a cédé (cause de la <span class=\"kw-clinique\">fièvre</span> + état neurologique)</p><ul><li><span class=\"kw-ttt\">Diazépam intrarectal</span> si la crise n'a pas cédé à <span class=\"kw-chiffre\">5 min</span></li><li>Persistance malgré cela → prévenir <span class=\"kw-clinique\">les</span> <strong>secours médicalisés</strong></li></ul>","suivi":"<p><strong>Risque principal = récidive</strong> d'une crise fébrile : <span class=\"kw-chiffre\">20–30 %</span> globalement. <strong>Piège :</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">antipyrétiques</span> ne préviennent <strong>pas</strong> la récurrence des crises fébriles.</p><p><strong><span class=\"kw-def\">Facteurs de risque</span> de récidive</strong></p><p>Gradient : <span class=\"kw-chiffre\">0 FR → 10 %</span> · <span class=\"kw-chiffre\">1 → 25 %</span> · <span class=\"kw-chiffre\">2 → 50 %</span> · <span class=\"kw-chiffre\">3 → 80 %</span></p><ul><li>1<sup>re</sup> crise avant <span class=\"kw-chiffre\">&lt; 15 mois</span></li><li><span class=\"kw-etio\">ATCD familial au 1<sup>er</sup> degré</span> de crise fébrile</li><li><span class=\"kw-clinique\">Fièvre</span> <span class=\"kw-chiffre\">&lt; 38,5 °C</span> lors de la crise</li><li>Crise survenue <strong>tôt</strong> dans l'épisode fébrile</li></ul><p><strong>Risque d'épilepsie ultérieure</strong></p><ul><li><span class=\"kw-alerte\">Retard psychomoteur</span></li><li>Examen neurologique antérieurement anormal (<span class=\"kw-clinique\">déficit focal</span>, hémiparésie)</li><li>Crises fébriles <span class=\"kw-alerte\">complexes</span> (focale et/ou prolongée et/ou répétitive sur <span class=\"kw-chiffre\">24 h</span>)</li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/neurologie/convulsions-crises-depilepsie-epilepsie","label":"Pédia-univ — Convulsions / crises d'épilepsie (référentiel)"}],"cards":[{"i":"0da1ecc49fcb","n":346,"o":"346-1","u":"Diagnostic positif","t":"Connaître les principaux tableaux cliniques d’une crise convulsive du nourrisson et du jeune enfant","q":"Quelle est la définition opérationnelle de l'état de mal convulsif chez le nourrisson et le jeune enfant ?","a":"<p>L'état de mal convulsif est défini comme des convulsions qui <strong>persistent au-delà de 5 minutes</strong>, nécessitant une prise en charge urgente spécifique.</p>"},{"i":"2bc00c3e10b2","n":346,"o":"346-1","u":"Diagnostic positif","t":"Connaître les principaux tableaux cliniques d’une crise convulsive du nourrisson et du jeune enfant","q":"Quels sont les principaux diagnostics différentiels à considérer face à des manifestations pouvant simuler des convulsions chez le nourrisson et le jeune enfant ?","a":"<ul><li>Les <strong>frissons</strong> : liés à l'ascension thermique ou une décharge bactérienne, avec des secousses moins amples et plus rapides.</li><li>Les <strong>trémulations</strong> : tremblements fins des extrémités, disparaissant à l'immobilisation forcée.</li><li>Les <strong>myoclonies du sommeil</strong> : survenant exclusivement à l'endormissement, dans le sommeil.</li><li>Les <strong>spasmes du sanglot</strong> : séquence pleurs / apnée / cyanose sur frustration, colère ou peur, entre 6 mois et 3 ans.</li><li>La <strong>syncope vagale convulsivante</strong> : perte de connaissance suivie de secousses des 4 membres.</li><li>Les <strong>mouvements anormaux</strong> : parfois effets secondaires de médicaments.</li><li>Les <strong>autres malaises</strong> : changement de teint brusque, rupture de contact, et hypotonie, sans mouvements anormaux.</li></ul>"},{"i":"a02e6c1d3013","n":346,"o":"346-1","u":"Diagnostic positif","t":"Connaître les principaux tableaux cliniques d’une crise convulsive du nourrisson et du jeune enfant","q":"Quelles sont les caractéristiques des crises généralisées tonicocloniques chez le nourrisson et le jeune enfant ?","a":"<p>Les crises généralisées tonicocloniques sont des manifestations convulsives <strong>rares avant l'âge de 2 ans</strong> chez le nourrisson et le jeune enfant.</p>"},{"i":"f8fef84e9f26","n":346,"o":"346-1","u":"Diagnostic positif","t":"Connaître les principaux tableaux cliniques d’une crise convulsive du nourrisson et du jeune enfant","q":"Comment est établi le diagnostic de convulsions chez le nourrisson et le jeune enfant, étant donné que les crises ont souvent déjà cessé ?","a":"<p>Le diagnostic de convulsions est purement <strong>clinique et anamnestique</strong>. Il repose principalement sur l'<strong>interrogatoire de l'enfant et des témoins</strong> de l'épisode, car aucun examen complémentaire ne confirme ni n'infirme une convulsion <em>a posteriori</em>.</p>"},{"i":"04378d5aa8b0","n":346,"o":"346-2","u":"Définition","t":"Connaître la définition d’une crise convulsive hyperthermique simple et d’une crise convulsive complexe","q":"Quels sont les critères qui définissent une crise convulsive hyperthermique complexe ?","a":"<p>La présence d'<strong>un seul</strong> des critères suivants suffit à classer une crise comme complexe :</p><ul><li>Âge de survenue <strong>&lt; 1 an</strong>.</li><li>Durée <strong>≥ 15 minutes</strong> ou <strong>plusieurs épisodes</strong> pour le même accès fébrile (&gt; 1 épisode/24h).</li><li>Crise à début <strong>localisé (focal)</strong> et non généralisée.</li><li>Présence d'un <strong>déficit post-critique</strong>.</li><li>Existence d'<strong>antécédents neurologiques</strong>.</li><li>Examen neurologique <strong>anormal</strong>.</li></ul>"},{"i":"6ebddcc6c0e4","n":346,"o":"346-2","u":"Définition","t":"Connaître la définition d’une crise convulsive hyperthermique simple et d’une crise convulsive complexe","q":"Quelle est la définition d'une crise convulsive hyperthermique (crise fébrile) ?","a":"<p>Une crise convulsive hyperthermique est une crise <strong>épileptique</strong> liée à la fièvre, survenant chez un enfant de <strong>6 mois à 5 ans</strong> (surtout entre 1 et 3 ans), ayant un développement psychomoteur <strong>normal</strong>, et en l'absence de toute atteinte du Système Nerveux Central (SNC).</p>"},{"i":"7c12d9ba08ae","n":346,"o":"346-2","u":"Définition","t":"Connaître la définition d’une crise convulsive hyperthermique simple et d’une crise convulsive complexe","q":"Quels sont les critères permettant de définir une crise convulsive hyperthermique simple ?","a":"<ul><li>Âge de début <strong>&gt; 1 an</strong>.</li><li>Fièvre <strong>&gt; 37,5 °C</strong> (la fièvre n'est pas obligatoirement présente au moment exact de la crise).</li><li>Manifestations motrices <strong>symétriques</strong>.</li><li>Durée <strong>≤ 15 minutes</strong>.</li><li><strong>Pas de déficit post-critique</strong>.</li><li><strong>Épisode unique</strong> pour un accès fébrile donné (et <strong>&lt; 3 épisodes au total</strong>).</li></ul>"},{"i":"59c56a39dfc7","n":346,"o":"346-3","u":"Étiologies","t":"Connaître les étiologies des crises convulsives du nourrisson et du jeune enfant","q":"Quelles sont les principales étiologies des crises convulsives sans fièvre chez le nourrisson et le jeune enfant ?","a":"<p>Les principales étiologies des crises convulsives sans fièvre sont :</p><ul><li>Un <strong>événement occasionnel sans suite</strong> (traumatisme crânien, hématome sous-dural).</li><li>La <strong>première crise d'une épilepsie débutante</strong>.</li><li>Les <strong>causes métaboliques</strong> (surtout avant 6 mois).</li><li>Un AVC.</li><li>Une tumeur cérébrale.</li><li>Une HTA.</li><li>Un SHU.</li><li>Une cause toxique.</li></ul>"},{"i":"5a5db07d8cb8","n":346,"o":"346-3","u":"Étiologies","t":"Connaître les étiologies des crises convulsives du nourrisson et du jeune enfant","q":"Quels sont les signes d'alerte devant faire évoquer un hématome sous-dural (HSD) ou épidural (HED) aigu en cas de convulsions chez le jeune nourrisson ?","a":"<p>Devant un HSD/HED aigu compliquant un traumatisme crânien chez le jeune nourrisson, il faut rechercher :</p><ul><li>Une <strong>fontanelle bombante</strong>.</li><li>Évoquer systématiquement une <strong>maltraitance</strong> dans ce contexte.</li></ul>"},{"i":"63496f8a736a","n":346,"o":"346-3","u":"Étiologies","t":"Connaître les étiologies des crises convulsives du nourrisson et du jeune enfant","q":"Quelles sont les causes métaboliques de crises convulsives chez le nourrisson et le jeune enfant, en particulier avant 6 mois ?","a":"<p>Les causes métaboliques de crises convulsives, prédominantes avant 6 mois, incluent :</p><ul><li>L'<strong>hyponatrémie</strong> ou l'<strong>hypernatrémie</strong>.</li><li>L'<strong>hypoglycémie</strong>.</li><li>L'<strong>hypocalcémie</strong>.</li></ul>"},{"i":"7d90762da9ec","n":346,"o":"346-3","u":"Étiologies","t":"Connaître les étiologies des crises convulsives du nourrisson et du jeune enfant","q":"Quelles sont les épilepsies spécifiques du nourrisson à connaître selon le programme de l'EDN ?","a":"<p>Les épilepsies du nourrisson à connaître sont :</p><ul><li>Le <strong>syndrome de West</strong>.</li><li>Le <strong>syndrome de Dravet</strong> (rare, génétique, principalement dû à une mutation <em>de novo</em> de SCN1A dans 90% des cas, caractérisé par des crises prolongées fébriles ou post-vaccinales dès la première année de vie).</li></ul>"},{"i":"e48e7bf0ded2","n":346,"o":"346-3","u":"Étiologies","t":"Connaître les étiologies des crises convulsives du nourrisson et du jeune enfant","q":"Quelles sont les principales étiologies des crises convulsives avec fièvre chez le nourrisson et le jeune enfant ?","a":"<p>Les principales étiologies des crises convulsives avec fièvre sont :</p><ul><li>La <strong>crise fébrile simple ou complexe</strong>, très fréquente.</li><li>L'<strong>infection neuroméningée</strong> (méningite bactérienne, encéphalite herpétique).</li><li>Plus rarement : neuropaludisme, abcès cérébral, thrombophlébite cérébrale, SHU.</li></ul>"},{"i":"3080e6f8d85b","n":346,"o":"346-4","u":"Identifier une urgence","t":"Connaître les signes de gravité à rechercher devant une crise convulsive du nourrisson et du jeune enfant","q":"Quels sont les signes de gravité liés à la crise convulsive elle-même chez le nourrisson ou l'enfant ?","a":"<p>Les signes de gravité liés à la crise convulsive elle-même incluent :</p><ul><li>Une <strong>durée prolongée</strong> : crise supérieure à 5 minutes (définition opérationnelle de l'état de mal nécessitant des benzodiazépines en urgence). Une crise de plus de 15 minutes est particulièrement grave.</li><li>Une <strong>récidive</strong> : crises se répétant sans retour à une conscience normale entre les épisodes.</li><li>Des <strong>signes neurologiques durables</strong> : signes focaux persistants, troubles de conscience prolongés ou s'aggravant.</li><li>Des <strong>signes respiratoires</strong> : comme la bradypnée, les irrégularités respiratoires, les apnées, la cyanose ou un encombrement bronchique majeur.</li><li>Des <strong>signes hémodynamiques</strong> : tels que la tachycardie, un temps de recoloration cutanée allongé, des marbrures, des extrémités froides ou des pouls périphériques mal perçus.</li></ul>"},{"i":"5db83df197aa","n":346,"o":"346-4","u":"Identifier une urgence","t":"Connaître les signes de gravité à rechercher devant une crise convulsive du nourrisson et du jeune enfant","q":"Quels sont les signes de gravité orientant vers une cause sous-jacente grave d'une crise convulsive chez le nourrisson ou l'enfant ?","a":"<p>Les signes de gravité orientant vers une cause sous-jacente grave sont :</p><ul><li><strong>Infectieux</strong> : signes de sepsis, purpura fébrile, cris geignards, syndrome méningé, ou signes encéphalitiques.</li><li><strong>Maltraitance</strong> : présence d'une pâleur inexpliquée ou d'hématomes multiples.</li><li><strong>Toxique</strong> : état de coma ou suspicion d'intoxication médicamenteuse.</li></ul>"},{"i":"caabeb8c648d","n":346,"o":"346-4","u":"Identifier une urgence","t":"Connaître les signes de gravité à rechercher devant une crise convulsive du nourrisson et du jeune enfant","q":"À partir de quel délai une crise convulsive doit-elle faire suspecter un état de mal et justifier une prise en charge urgente ?","a":"<p>Une crise convulsive doit faire suspecter un <strong>état de mal</strong> et justifier une prise en charge urgente si elle dure <strong>plus de 5 minutes</strong>.</p><p>De même, une prise en charge en urgence s'impose si la crise est récidivante sans reprise de conscience ou si elle est associée à des signes respiratoires ou hémodynamiques graves.</p>"},{"i":"0f5c65d245c0","n":346,"o":"346-5","u":"Prise en charge","t":"Connaître les principes de prise en charge thérapeutique de première intention d’une crise convulsive du nourrisson et du jeune enfant avec la posologie des benzodiazépines par voie rectale (clonazepam ou diazepam)","q":"Quelle est la conduite à tenir en cas de récidive d'une crise convulsive à domicile chez le nourrisson ou le jeune enfant ?","a":"<ul><li>Si la crise n'a pas cédé après 5 minutes, administrer le <strong>diazépam intrarectal</strong>.</li><li>Si la crise persiste malgré cette administration, <strong>prévenir les secours médicalisés</strong>.</li><li>Une <strong>consultation médicale systématique</strong> est impérative, même si la crise a cédé, pour rechercher la cause de la fièvre et vérifier l'état neurologique.</li></ul>"},{"i":"5cfd66c3bcdb","n":346,"o":"346-5","u":"Prise en charge","t":"Connaître les principes de prise en charge thérapeutique de première intention d’une crise convulsive du nourrisson et du jeune enfant avec la posologie des benzodiazépines par voie rectale (clonazepam ou diazepam)","q":"Comment doit être prise en charge une crise convulsive du nourrisson ou du jeune enfant qui a cessé spontanément ?","a":"<p>Si les convulsions ont cédé spontanément, il faut administrer un <strong>antipyrétique</strong> en cas de fièvre, et instaurer un traitement étiologique.</p>"},{"i":"62346b9ebc40","n":346,"o":"346-5","u":"Prise en charge","t":"Connaître les principes de prise en charge thérapeutique de première intention d’une crise convulsive du nourrisson et du jeune enfant avec la posologie des benzodiazépines par voie rectale (clonazepam ou diazepam)","q":"Quelle est la conduite à tenir si le traitement de première intention d'une crise convulsive chez le nourrisson ou le jeune enfant est un échec après 10 minutes ?","a":"<p>En cas d'échec après <strong>10 minutes</strong> (soit 5 minutes après la première injection), une <strong>deuxième dose de benzodiazépine</strong> doit être administrée, de préférence par voie <strong>intraveineuse (IV)</strong> en milieu hospitalier (par exemple, <strong>clonazépam IVL</strong>).</p>"},{"i":"732c2c288f4a","n":346,"o":"346-5","u":"Prise en charge","t":"Connaître les principes de prise en charge thérapeutique de première intention d’une crise convulsive du nourrisson et du jeune enfant avec la posologie des benzodiazépines par voie rectale (clonazepam ou diazepam)","q":"Quelle est la posologie du diazépam intrarectal à retenir pour la prise en charge d'une crise convulsive chez le nourrisson ou le jeune enfant ?","a":"<p>La posologie à retenir est <strong>0,5 mg/kg</strong> de diazépam par voie <strong>intrarectale</strong>, avec un maximum de <strong>10 mg</strong>, si la crise dure <strong>plus de 5 minutes</strong>.</p>"},{"i":"8c2f5b1c07a7","n":346,"o":"346-5","u":"Prise en charge","t":"Connaître les principes de prise en charge thérapeutique de première intention d’une crise convulsive du nourrisson et du jeune enfant avec la posologie des benzodiazépines par voie rectale (clonazepam ou diazepam)","q":"Quelle est la définition opérationnelle de l'état de mal épileptique menaçant chez le nourrisson ou le jeune enfant, et à partir de quand doit-on intervenir lors d'une crise convulsive ?","a":"<p>L'état de mal épileptique (EME) menaçant est défini par une crise qui dure <strong>plus de 5 minutes</strong>. C'est le seuil à partir duquel une intervention thérapeutique de première intention est déclenchée.</p>"},{"i":"92e15135c6be","n":346,"o":"346-5","u":"Prise en charge","t":"Connaître les principes de prise en charge thérapeutique de première intention d’une crise convulsive du nourrisson et du jeune enfant avec la posologie des benzodiazépines par voie rectale (clonazepam ou diazepam)","q":"Quelles sont les mesures générales initiales à prendre devant une crise convulsive persistante chez le nourrisson ou le jeune enfant ?","a":"<ul><li>Assurer la <strong>liberté des voies aériennes supérieures</strong> : mise en <strong>position latérale de sécurité (PLS)</strong>. (Attention : pas de canule de Guedel).</li><li>Réaliser un <strong>monitoring cardiorespiratoire</strong>.</li><li>Prendre les <strong>constantes</strong> vitales, incluant la température.</li></ul>"},{"i":"b6ff865fadd5","n":346,"o":"346-5","u":"Prise en charge","t":"Connaître les principes de prise en charge thérapeutique de première intention d’une crise convulsive du nourrisson et du jeune enfant avec la posologie des benzodiazépines par voie rectale (clonazepam ou diazepam)","q":"Quel est le traitement de première intention (crise > 5 min) pour une crise convulsive persistante chez le nourrisson ou le jeune enfant?","a":"<p>Le traitement de première intention est une <strong>benzodiazépine</strong> :</p><ul><li><strong>Diazépam 0,5 mg/kg</strong> (maximum <strong>10 mg</strong>) en voie <strong>intrarectale</strong>.</li><li>Ou <strong>midazolam buccal</strong>.</li></ul>"},{"i":"2bca555d33df","n":346,"o":"346-7","u":"Suivi et/ou pronostic","t":"Connaître le pronostic d’une crise convulsive du nourrisson et du jeune enfant","q":"Quels sont les facteurs de risque d'épilepsie ultérieure après une crise convulsive chez le nourrisson ou l'enfant ?","a":"<p>Les facteurs de risque d'épilepsie ultérieure après une crise convulsive sont :</p><ul><li>Un <strong>retard psychomoteur</strong>.</li><li>Un <strong>examen neurologique antérieurement anormal</strong> (déficit focal, hémiparésie).</li><li>La présence de <strong>crises fébriles complexes</strong>.</li></ul>"},{"i":"822a7fa2b825","n":346,"o":"346-7","u":"Suivi et/ou pronostic","t":"Connaître le pronostic d’une crise convulsive du nourrisson et du jeune enfant","q":"Quels sont les facteurs prédictifs d'une infection cérébroméningée après une crise convulsive chez le nourrisson ou l'enfant ?","a":"<p>Les facteurs prédictifs d'une infection cérébroméningée sont :</p><ul><li>La présence d'un <strong>syndrome méningé</strong>.</li><li>Les critères de <strong>crise fébrile complexe</strong> : crise focale, et/ou prolongée, et/ou répétitive sur 24 heures.</li></ul>"},{"i":"969826092934","n":346,"o":"346-7","u":"Suivi et/ou pronostic","t":"Connaître le pronostic d’une crise convulsive du nourrisson et du jeune enfant","q":"Quels sont les facteurs de risque de récidive d'une crise fébrile chez le nourrisson ou l'enfant ?","a":"<p>Les facteurs de risque d'une récidive de crise fébrile sont :</p><ul><li>Une <strong>première crise avant 15 mois</strong>.</li><li>Des <strong>antécédents familiaux au premier degré</strong> de crises fébriles.</li><li>Une <strong>fièvre < 38,5 °C</strong> lors de la crise initiale.</li><li>Une crise survenue <strong>tôt dans l'épisode fébrile</strong>.</li></ul>"},{"i":"df8e3d90939f","n":346,"o":"346-7","u":"Suivi et/ou pronostic","t":"Connaître le pronostic d’une crise convulsive du nourrisson et du jeune enfant","q":"Quel est le risque global de récidive d'une crise fébrile chez le nourrisson ou l'enfant, et comment évolue-t-il en fonction des facteurs de risque ?","a":"<p>Le risque global de récidive d'une crise fébrile est de <strong>20 à 30 %</strong>. Il existe un gradient selon le nombre de facteurs de risque :</p><ul><li><strong>0 facteur de risque</strong> : 10 %</li><li><strong>1 facteur de risque</strong> : 25 %</li><li><strong>2 facteurs de risque</strong> : 50 %</li><li><strong>3 facteurs de risque</strong> : 80 %</li></ul>"},{"i":"e9af90f516e0","n":346,"o":"346-7","u":"Suivi et/ou pronostic","t":"Connaître le pronostic d’une crise convulsive du nourrisson et du jeune enfant","q":"Dans quelles situations un avis neuropédiatrique est-il requis après une crise fébrile chez le nourrisson ou l'enfant ?","a":"<p>Un avis neuropédiatrique est requis dans les situations suivantes :</p><ul><li>Crise fébrile prolongée <strong>avant 1 an</strong> (pour évoquer un <strong>syndrome de Dravet</strong>).</li><li>Crise <strong>focale et prolongée</strong> ou <strong>focale et répétitive</strong>.</li><li>Répétition d'une <strong>crise complexe</strong>.</li><li>Présence d'un <strong>retard de développement</strong> ou d'une <strong>anomalie à l'examen neurologique</strong>.</li></ul>"}]};